package marked

import (
	"bufio"
	"encoding/json"
	"os"
	osexec "os/exec"
	"strings"
	"testing"
)

// TestDifferentialAgainstMarked compares the port against marked 18.0.11 on
// the cases of testdata/differential.txt.
//
// The reference is generated by scripts/marked-tokens.mjs, which runs the
// published marked package. The test is skipped when node is not available.
func TestDifferentialAgainstMarked(t *testing.T) {
	node, err := osexec.LookPath("node")
	if err != nil {
		t.Skip("node is not available")
	}

	data, err := os.ReadFile("testdata/differential.txt")
	if err != nil {
		t.Fatalf("read cases: %v", err)
	}

	cases := strings.Split(string(data), "\n---\n")
	for _, markdown := range cases {
		if markdown == "" {
			continue
		}
		markdown := markdown
		t.Run(shortName(markdown), func(t *testing.T) {
			want := referenceTokens(t, node, markdown)
			tokens, _ := Lex(markdown, DefaultOptions())
			got := canonicalTokens(tokens)
			if normalizeJSON(got) != normalizeJSON(want) {
				t.Fatalf("token stream differs\nmarkdown: %q\ngot:  %s\nwant: %s",
					markdown, compactJSON(got), compactJSON(want))
			}
		})
	}
}

// referenceTokens runs marked over one input and decodes its token stream.
func referenceTokens(t *testing.T, node string, markdown string) []any {
	t.Helper()

	cmd := osexec.Command(node, "../../../scripts/marked-tokens.mjs")
	cmd.Stdin = strings.NewReader(markdown)
	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()
	if err != nil {
		// The script reports a missing marked module with status 3. The
		// live comparison is a development aid; the frozen corpus of
		// testdata/tokens.json is the oracle.
		if exit, ok := err.(*osexec.ExitError); ok && exit.ExitCode() == 3 {
			t.Skipf("marked 18.0.11 is not available: %s", strings.TrimSpace(stderr.String()))
		}
		t.Fatalf("run marked: %v: %s", err, stderr.String())
	}

	var tokens []any
	if err := json.Unmarshal([]byte(strings.TrimSpace(stdout.String())), &tokens); err != nil {
		t.Fatalf("decode marked output: %v: %q", err, stdout.String())
	}
	return tokens
}

// shortName builds a readable name for a test case.
func shortName(markdown string) string {
	var out strings.Builder
	for _, r := range markdown {
		switch {
		case r == '\n':
			out.WriteByte('_')
		case r == ' ':
			out.WriteByte('-')
		default:
			out.WriteRune(r)
		}
	}
	name := out.String()
	if len(name) > 60 {
		name = name[:60]
	}
	return name
}

// readLines reads a file line by line, for the fuzz corpus helper.
func readLines(t *testing.T, path string) []string {
	t.Helper()

	file, err := os.Open(path)
	if err != nil {
		t.Fatalf("open %s: %v", path, err)
	}
	defer file.Close()

	var lines []string
	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	if err := scanner.Err(); err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	return lines
}
